  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = i === n ? 1 : 1 - Math.exp(-zeta * w * t) * (Math.cos(wd * t) + (zeta * w / wd) * Math.sin(wd * t));
    pts.push(+x.toFixed(4));
  }
  return `linear(${pts.join(', ')})`;
}
