    lg.gain.value = lvl;
    o.connect(lg).connect(g);
    o.start(t); o.stop(t + dur + 0.05);
  }
}

// A breath of filtered noise: whooshes and taps.
function air({ at = 0, dur = 0.25, vol = 0.08, from = 800, to = 3000, q = 0.8 } = {}) {
