+const newer = (a, b) => { for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] > b[i]; return false; };
+const TYPES = [
+  ['feature', /^(✨|🎉|🚀|feat\b)/u, 'New'],
+  ['design', /^(💄|💫|🎨|🍱|style\b)/u, 'Look and feel'],
+  ['fix', /^(🐛|🚑️?|🩹|fix\b)/u, 'Fixes'],
+  ['perf', /^(⚡️?|perf\b)/u, 'Faster'],
+];
